const LISTENERS_KEY = Symbol.for("@agent-native/core.workspace-connection-lifecycle-listeners");
function listeners() {
    const global = globalThis;
    global[LISTENERS_KEY] ??= new Set();
    return global[LISTENERS_KEY];
}
export function registerWorkspaceConnectionLifecycleListener(listener) {
    listeners().add(listener);
    return () => listeners().delete(listener);
}
export async function notifyWorkspaceConnectionLifecycle(event) {
    await Promise.all([...listeners()].map((listener) => Promise.resolve(listener(event))));
}
